import { expoClient } from "@better-auth/expo/client";
import { createAuthClient } from "better-auth/react";
import * as SecureStore from "expo-secure-store";

export const AUTH_BASE_URL =
	process.env.EXPO_PUBLIC_API_URL ?? "https://scorebrawl.localhost:1355";

export const authClient = createAuthClient({
	baseURL: AUTH_BASE_URL,
	plugins: [
		expoClient({
			scheme: "scorebrawl",
			storagePrefix: "scorebrawl",
			storage: SecureStore,
		}),
	],
});

export const isEmailPasswordEnabled =
	process.env.EXPO_PUBLIC_DISABLE_EMAIL_PASSWORD !== "true";

export const isGithubEnabled = Boolean(process.env.EXPO_PUBLIC_GITHUB_CLIENT_ID);

export const isGoogleEnabled = Boolean(process.env.EXPO_PUBLIC_GOOGLE_CLIENT_ID);

